"""Golden results for the JavaScript engine (frontend/src/engine), computed by
the Python reference (backend/app). tests/engine.test.mjs checks that the
JavaScript gives exactly the same roll tables, Upcoming lists, search results
and "I followed this path" results.

Writes golden.json next to this file, with everything it needs inside (the
banner data and the part of the Cat Guide list used), so it never changes when
the shipped data does. Rerun after changing either engine on purpose:

    backend/.venv/Scripts/python.exe frontend/tests/fixtures/make_golden.py
"""

from __future__ import annotations

import datetime as dt
import hashlib
import json
import os
import sys
import time

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, "..", "..", ".."))
sys.path.insert(0, os.path.join(ROOT, "backend"))

from app import godfat_data, pathfinder, services  # noqa: E402
from app.master import MasterData  # noqa: E402
from app.names import NameMatcher, normalize  # noqa: E402

# Banner data, frozen: godfat's events from the scraped-table fixture (Dec
# 2025, guaranteed banners and a Legend Capsule), and the data shipped on
# 2026-10-23 (Platinum/Legend Capsules and normal banners).
DATASETS = {
    "fixture": os.path.join(ROOT, "backend", "tests", "fixtures", "godfat_fixture_data.json"),
    "now": os.path.join(HERE, "godfat_data_2026-10-23.json"),
}
MASTER = os.path.join(ROOT, "backend", "data", "cat_guide_master.json")
TABLE_SEEDS = [139026851, 0, 4294967295, 2718281828, 123456789]


def canonical(value) -> str:
    return json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(",", ":"))


def digest(value) -> str:
    return hashlib.sha256(canonical(value).encode("utf-8")).hexdigest()


def at_day(day: str):
    """Make Dataset.upcoming() use `day` as today (ingest calls it)."""
    original = godfat_data.Dataset.upcoming
    fixed = dt.date.fromisoformat(day)

    def upcoming(self, today=None):
        return original(self, today or fixed)

    godfat_data.Dataset.upcoming = upcoming
    return lambda: setattr(godfat_data.Dataset, "upcoming", original)


def main() -> int:
    raw = {name: godfat_data.load_file(path) for name, path in DATASETS.items()}
    datasets = {name: godfat_data.Dataset(data) for name, data in raw.items()}

    # The part of the Cat Guide list these banners use.
    full = json.load(open(MASTER, encoding="utf-8"))
    names = {normalize(c[0]) for data in raw.values() for c in data["cats"].values()}
    units = [u for u in full["units"] if normalize(u["name"]) in names]
    master_json = {"_meta": full["_meta"], "units": units}
    master = MasterData.__new__(MasterData)  # MasterData() reads a file; this is the same, from memory
    master.path, master.meta, master.units = None, master_json["_meta"], units
    master.region = master.meta.get("region", "BCEN (English)")
    master.by_index = {u["global_index"]: u for u in units}
    master.matcher = NameMatcher(units)

    golden: dict = {
        "_about": "Generated by make_golden.py from the Python engine; do not edit.",
        "datasets": raw,
        "master": master_json,
        "tables": [],
        "upcoming": [],
        "searches": [],
        "followed": [],
    }

    # Roll tables: every event of both datasets, several seeds.
    for name, ds in datasets.items():
        count = 100 if name == "fixture" else 300
        for event_id in ds.events:
            for seed in TABLE_SEEDS:
                banner = ds.banner(seed, event_id, count)
                if banner is None:
                    golden["tables"].append({"data": name, "event_id": event_id, "seed": seed, "count": count,
                                             "none": True})
                    continue
                golden["tables"].append({"data": name, "event_id": event_id, "seed": seed, "count": count,
                                         "cells": len(banner.rolls), "first": banner.rolls["1A"],
                                         "digest": digest(banner.rolls)})
    # One deep table.
    deep = datasets["fixture"].banner(139026851, "2025-12-09_1019", 1000)
    golden["tables"].append({"data": "fixture", "event_id": "2025-12-09_1019", "seed": 139026851, "count": 1000,
                             "cells": len(deep.rolls), "first": deep.rolls["1A"], "digest": digest(deep.rolls)})

    # Upcoming lists.
    for name, day in (("now", "2026-10-23"), ("now", "2026-10-24"), ("now", "2026-11-01"),
                      ("fixture", "2025-12-10"), ("fixture", "2025-12-13")):
        events = datasets[name].upcoming(dt.date.fromisoformat(day))
        golden["upcoming"].append({"data": name, "today": day, "events": [e.to_dict() for e in events]})

    # Searches.
    fixture_table = datasets["fixture"].banner(139026851, "2025-12-09_1019", 100).rolls
    guaranteed_ubers = list(dict.fromkeys(e["guaranteed_unit"] for e in fixture_table.values()
                                          if e.get("guaranteed_unit")))[:3]
    dupe_units = list(dict.fromkeys(e["alt_unit"] for e in fixture_table.values() if e.get("alt_unit")))[:2]
    res = {"rare_tickets": 30, "cat_food": 45000, "platinum_tickets": 2, "legend_tickets": 2}
    now_ids = ["2026-10-16_1071", "2026-10-16_1072", "2026-10-20_1070", "2026-10-23_1015", "2026-10-23_946"]
    wish = ["Sorceress Sidmi", "Hanasaka Cat", "Lone Moon Lunos"]
    all_now = [e.event_id for e in datasets["now"].upcoming(dt.date(2026, 10, 23))]
    every_index = [u["global_index"] for u in units]
    scenarios = [
        ("wishlist with special banners", "now", "2026-10-23", 1_500_000,
         dict(seed="139026851", event_ids=now_ids, count=100, resources=res, owned=[], wishlist=wish)),
        ("owned collection, step cap", "now", "2026-10-23", 30_000,
         dict(seed="2718281828", event_ids=["2026-10-20_1070", "2026-10-23_946", "2026-10-26_926"], count=60,
              resources={"rare_tickets": 10, "cat_food": 3000}, owned=every_index[: len(every_index) // 2],
              wishlist=None)),
        ("guaranteed banners", "fixture", "2025-12-10", 200_000,
         dict(seed="139026851", event_ids=["2025-12-09_1019", "2025-12-12_1005", "2025-11-07_996", "nope"],
              count=80, resources={"rare_tickets": 5, "cat_food": 15000, "legend_tickets": 1}, owned=[],
              wishlist=guaranteed_ubers)),
        ("dupe paths", "fixture", "2025-12-10", 100_000,
         dict(seed="139026851", event_ids=["2025-12-09_1019", "2025-04-28_946"], count=100,
              resources={"cat_food": 30000}, owned=[], wishlist=dupe_units)),
        ("strict mode", "now", "2026-10-23", 100_000,
         dict(seed="139026851", event_ids=now_ids, count=100, resources=res, owned=[], wishlist=wish,
              mode=pathfinder.MODE_STRICT)),
        ("best-effort mode", "now", "2026-10-23", 50_000,
         dict(seed="139026851", event_ids=now_ids, count=100, resources={}, owned=[], wishlist=wish,
              mode=pathfinder.MODE_BEST_EFFORT)),
        ("nothing affordable", "now", "2026-10-23", 1_500_000,
         dict(seed="139026851", event_ids=now_ids, count=100, resources={}, owned=[], wishlist=wish)),
        ("everything owned", "now", "2026-10-23", 1_500_000,
         dict(seed="139026851", event_ids=now_ids, count=100, resources=res, owned=every_index, wishlist=None)),
        ("every banner, no wishlist (big target mask)", "now", "2026-10-23", 20_000,
         dict(seed="139026851", event_ids=all_now, count=100, resources=res, owned=[], wishlist=None)),
    ]
    for title, name, day, max_steps, body in scenarios:
        restore = at_day(day)
        try:
            body = {"mode": pathfinder.MODE_RESOURCE_LIMIT, "max_solutions": 20, **body}
            resources = pathfinder.normalize_resources(body["resources"])
            t = time.perf_counter()
            ingestion = godfat_data.ingest(datasets[name], body["seed"], body["count"], resources=resources,
                                           event_ids=set(body["event_ids"]))
            result = services.run_search(ingestion.banners, master, set(body["owned"]), resources,
                                         wishlist=body["wishlist"], mode=body["mode"], max_steps=max_steps,
                                         max_solutions=body["max_solutions"])
            took = time.perf_counter() - t
        finally:
            restore()
        result["skipped"] = ingestion.skipped
        first = result["solutions"][0] if result["solutions"] else None
        golden["searches"].append({
            "title": title, "data": name, "today": day, "max_steps": max_steps, "body": body,
            "digest": digest(result),
            "summary": {
                "targets": len(result["targets"]),
                "solutions": len(result["solutions"]),
                "skipped": result["skipped"],
                "best_cost": first and first["cost"],
                "best_steps": first and [f"{a['banner_index']}:{a['action_type']}:{a['position_from']}>{a['position_to']}"
                                         for a in first["actions"]],
            },
            "python_seconds": round(took, 2),
        })
        print(f"{title}: {len(result['targets'])} targets, {len(result['solutions'])} solutions, {took:.1f} s")

        # "I followed this path" on the best path of the first two searches.
        if first and len(golden["followed"]) < 2:
            owned = body["owned"][:5] + [first["units_pulled_all"][0]["global_index"]]
            golden["followed"].append({
                "solution": first, "owned": owned, "resources": body["resources"],
                "result": services.followed_result(master, first, set(owned), body["resources"]),
            })

    out = os.path.join(HERE, "golden.json")
    with open(out, "w", encoding="utf-8", newline="\n") as f:
        json.dump(golden, f, ensure_ascii=False, separators=(",", ":"))
        f.write("\n")
    print(f"Wrote {out}: {len(golden['tables'])} tables, {len(golden['searches'])} searches "
          f"({os.path.getsize(out) // 1024} KB)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
